            crs.to("unknowncomponentxyz:foo", 1, String.class);
            Assert.fail("Expected exception");
        } catch (IllegalStateException e) {
            Assert.assertTrue(e.getMessage().contains("unknowncomponentxyz:foo"));
        }
    }
}
